def get_stock_info(ticker, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _dt_iso(d):
        if isinstance(d, str):
            return d
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_boundary(d):
        d = d.astimezone(datetime.timezone.utc)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{hashlib.sha256((prefix+str(time.time())+str(random.random())).encode()).hexdigest()[:16]}"

    def _log_request(finance_requests, api_client_id, security_id, tool_name, raw_ticker, parameters, status, http_status_code=None, error_code=None, error_message=None, cache_key=None, response_snapshot_id=None, duration_ms=None):
        rid = _gen_id("freq")
        ts = now
        row = {
            "id": rid,
            "api_client_id": api_client_id,
            "security_id": security_id,
            "tool_name": tool_name,
            "ticker": raw_ticker,
            "parameters": parameters if isinstance(parameters, dict) else {},
            "status": status,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": cache_key,
            "response_snapshot_id": response_snapshot_id,
            "duration_ms": duration_ms,
            "created_at": _dt_iso(ts),
            "updated_at": _dt_iso(ts),
        }
        finance_requests.append(row)
        return rid

    def _select_authorized_client(api_clients, finance_requests):
        eligible = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not eligible:
            return None, _err("UNAUTHORIZED", "No active API client available to serve this request.")
        one_min_ago = now - datetime.timedelta(minutes=1)
        today = _day_boundary(now)

        for c in eligible:
            rpm_limit = c.get("requests_per_minute_limit")
            day_limit = c.get("requests_per_day_limit")
            if not isinstance(rpm_limit, int) or rpm_limit < 1:
                continue
            if not isinstance(day_limit, int) or day_limit < 1:
                continue
            cday = _dt_parse(c.get("current_day"))
            if cday is None or _day_boundary(cday) != today:
                c["current_day"] = _dt_iso(today)
                c["requests_today"] = 0
                c["updated_at"] = _dt_iso(now)
            req_today = c.get("requests_today")
            if not isinstance(req_today, int) or req_today < 0:
                c["requests_today"] = 0
                req_today = 0
            if req_today >= day_limit:
                continue
            cnt = 0
            for r in finance_requests:
                if r.get("api_client_id") != c.get("id"):
                    continue
                t = _dt_parse(r.get("created_at"))
                if t is None:
                    continue
                if t >= one_min_ago:
                    cnt += 1
                    if cnt >= rpm_limit:
                        break
            if cnt >= rpm_limit:
                continue
            return c, None

        any_day_block = False
        today = _day_boundary(now)
        for c in eligible:
            cday = _dt_parse(c.get("current_day"))
            if cday is None or _day_boundary(cday) != today:
                continue
            req_today = c.get("requests_today")
            if isinstance(req_today, int) and isinstance(c.get("requests_per_day_limit"), int) and req_today >= c.get("requests_per_day_limit"):
                any_day_block = True
                break
        if any_day_block:
            return None, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None, _err("RATE_LIMIT", "Per-minute rate limit exceeded.")

    def _resolve_or_create_security(securities, raw_ticker):
        tnorm = raw_ticker.strip()
        for s in securities:
            if not isinstance(s, dict):
                continue
            st = s.get("ticker")
            if isinstance(st, str) and st.lower() == tnorm.lower():
                return s, False
        sid = _gen_id("sec")
        ts = _dt_iso(now)
        row = {
            "id": sid,
            "ticker": tnorm,
            "exchange": None,
            "quote_type": None,
            "short_name": None,
            "long_name": None,
            "currency": None,
            "country": None,
            "sector": None,
            "industry": None,
            "status": "unknown",
            "created_at": ts,
            "updated_at": ts,
        }
        securities.append(row)
        return row, True

    def _find_snapshot(snapshots, security_id, dataset, params_fingerprint):
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("security_id") == security_id and s.get("dataset") == dataset and s.get("params_fingerprint") == params_fingerprint:
                return s
        return None

    def _snapshot_status_valid(snap):
        if not isinstance(snap, dict):
            return False
        if snap.get("status") != "fresh":
            return False
        exp = _dt_parse(snap.get("expires_at"))
        if exp is None:
            return False
        return exp > now

    def _upsert_snapshot(snapshots, security_id, dataset, params_fingerprint, payload, ttl_seconds=300, as_of=None, status="fresh"):
        if not isinstance(ttl_seconds, int):
            ttl_seconds = 300
        ttl_seconds = max(30, min(2592000, ttl_seconds))
        snap = _find_snapshot(snapshots, security_id, dataset, params_fingerprint)
        ts = _dt_iso(now)
        expires = now + datetime.timedelta(seconds=ttl_seconds)
        if snap is None:
            sid = _gen_id("snap")
            snap = {
                "id": sid,
                "security_id": security_id,
                "dataset": dataset,
                "params_fingerprint": params_fingerprint,
                "source": "yahoo_finance",
                "status": status,
                "as_of": _dt_iso(as_of) if as_of else None,
                "ttl_seconds": ttl_seconds,
                "expires_at": _dt_iso(expires),
                "payload": payload,
                "payload_schema_version": 1,
                "upstream_etag": None,
                "upstream_fetched_at": ts,
                "created_at": ts,
                "updated_at": ts,
            }
            snapshots.append(snap)
        else:
            allowed = {
                "fresh": {"stale", "expired", "error"},
                "stale": {"fresh", "expired", "error"},
                "expired": {"fresh", "error"},
                "error": {"fresh", "expired"},
            }
            cur = snap.get("status")
            if cur in allowed and status != cur and status not in allowed[cur]:
                status = "error"
            snap["status"] = status
            snap["as_of"] = _dt_iso(as_of) if as_of else snap.get("as_of")
            snap["ttl_seconds"] = ttl_seconds
            snap["expires_at"] = _dt_iso(expires)
            snap["payload"] = payload
            snap["payload_schema_version"] = max(1, int(snap.get("payload_schema_version") or 1))
            snap["upstream_fetched_at"] = ts
            snap["updated_at"] = ts
        return snap

    def _synthetic_upstream_info(security):
        t = (security.get("ticker") or "").strip()
        tl = t.lower()
        if tl.endswith(".invalid") or "invalid" in tl or tl in {"", "null"}:
            return {"ok": False, "reason": "invalid"}
        if "delist" in tl or tl.endswith(".delisted"):
            return {"ok": False, "reason": "delisted"}
        payload = {
            "symbol": t,
            "shortName": security.get("short_name") or t,
            "longName": security.get("long_name") or t,
            "quoteType": security.get("quote_type") or "EQUITY",
            "currency": security.get("currency") or "USD",
            "exchange": security.get("exchange") or None,
            "profile": {
                "country": security.get("country"),
                "sector": security.get("sector"),
                "industry": security.get("industry"),
            },
            "market": {
                "regularMarketPrice": round(50 + (hash(tl) % 10000) / 100.0, 4),
                "regularMarketChangePercent": round(((hash((tl, "chg")) % 2000) - 1000) / 100.0, 4),
            },
            "asOf": _dt_iso(now),
        }
        return {"ok": True, "payload": payload, "as_of": now}

    if not isinstance(ticker, str) or not ticker.strip():
        api_clients = _load("api_clients.json")
        finance_requests = _load("finance_requests.json")
        client = None
        for c in api_clients:
            if isinstance(c, dict):
                client = c
                break
        if client:
            duration_ms = int((time.time() - start_ts) * 1000)
            _log_request(finance_requests, client.get("id"), None, "get_stock_info", ticker if isinstance(ticker, str) else "", {}, "failed", 400, "VALIDATION_ERROR", "ticker must be a non-empty string.", None, None, duration_ms)
            _save("finance_requests.json", finance_requests)
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string.")

    api_clients = _load("api_clients.json")
    securities = _load("securities.json")
    finance_requests = _load("finance_requests.json")
    finance_snapshots = _load("finance_snapshots.json")

    client, auth_err = _select_authorized_client(api_clients, finance_requests)
    if client is None:
        any_client_id = None
        for c in api_clients:
            if isinstance(c, dict) and c.get("id"):
                any_client_id = c.get("id")
                break
        duration_ms = int((time.time() - start_ts) * 1000)
        _log_request(finance_requests, any_client_id or "unknown", None, "get_stock_info", ticker, {}, "failed", 429, auth_err["error"]["code"], auth_err["error"]["message"], None, None, duration_ms)
        _save("finance_requests.json", finance_requests)
        if any_client_id:
            _save("api_clients.json", api_clients)
        return auth_err

    sec, _created = _resolve_or_create_security(securities, ticker)
    dataset = "stock_info"
    params_fingerprint = "default"
    cache_key = f"{dataset}:{sec['id']}:{params_fingerprint}"

    snap = _find_snapshot(finance_snapshots, sec["id"], dataset, params_fingerprint)
    if snap is not None and _snapshot_status_valid(snap) and isinstance(snap.get("payload"), (dict, list)):
        duration_ms = int((time.time() - start_ts) * 1000)
        _log_request(finance_requests, client["id"], sec["id"], "get_stock_info", ticker, {}, "served_from_cache", 200, None, None, cache_key, snap.get("id"), duration_ms)
        client["requests_today"] = int(client.get("requests_today") or 0) + 1
        client["updated_at"] = _dt_iso(now)
        _save("api_clients.json", api_clients)
        _save("securities.json", securities)
        _save("finance_requests.json", finance_requests)
        _save("finance_snapshots.json", finance_snapshots)
        return {"ticker": ticker, "source": "cache", "snapshot_id": snap.get("id"), "data": snap.get("payload")}

    upstream = _synthetic_upstream_info(sec)
    if not upstream.get("ok"):
        reason = upstream.get("reason")
        if reason == "delisted":
            if sec.get("status") != "delisted":
                sec["status"] = "delisted"
                sec["updated_at"] = _dt_iso(now)
        elif reason == "invalid":
            if sec.get("status") == "unknown":
                sec["status"] = "inactive"
                sec["updated_at"] = _dt_iso(now)
        duration_ms = int((time.time() - start_ts) * 1000)
        _log_request(finance_requests, client["id"], sec.get("id"), "get_stock_info", ticker, {}, "failed", 404, "NOT_FOUND", "Ticker could not be resolved on Yahoo Finance.", cache_key, None, duration_ms)
        client["requests_today"] = int(client.get("requests_today") or 0) + 1
        client["updated_at"] = _dt_iso(now)
        _save("api_clients.json", api_clients)
        _save("securities.json", securities)
        _save("finance_requests.json", finance_requests)
        _save("finance_snapshots.json", finance_snapshots)
        return _err("NOT_FOUND", "Ticker could not be resolved on Yahoo Finance.")

    payload = upstream["payload"]
    snap = _upsert_snapshot(finance_snapshots, sec["id"], dataset, params_fingerprint, payload, ttl_seconds=300, as_of=upstream.get("as_of") or now, status="fresh")

    if sec.get("status") in {"unknown", "inactive"}:
        sec["status"] = "active"
        sec["updated_at"] = _dt_iso(now)

    duration_ms = int((time.time() - start_ts) * 1000)
    _log_request(finance_requests, client["id"], sec["id"], "get_stock_info", ticker, {}, "fetched_from_yahoo", 200, None, None, cache_key, snap.get("id"), duration_ms)
    client["requests_today"] = int(client.get("requests_today") or 0) + 1
    client["updated_at"] = _dt_iso(now)

    _save("api_clients.json", api_clients)
    _save("securities.json", securities)
    _save("finance_requests.json", finance_requests)
    _save("finance_snapshots.json", finance_snapshots)

    return {"ticker": ticker, "source": "yahoo_finance", "snapshot_id": snap.get("id"), "data": payload}

def get_yahoo_finance_news(ticker, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _dt_iso(d):
        if isinstance(d, str):
            return d
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_boundary(d):
        d = d.astimezone(datetime.timezone.utc)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{hashlib.sha256((prefix+str(time.time())+str(random.random())).encode()).hexdigest()[:16]}"

    def _log_request(finance_requests, api_client_id, security_id, tool_name, raw_ticker, parameters, status, http_status_code=None, error_code=None, error_message=None, cache_key=None, response_snapshot_id=None, duration_ms=None):
        rid = _gen_id("freq")
        ts = now
        row = {
            "id": rid,
            "api_client_id": api_client_id,
            "security_id": security_id,
            "tool_name": tool_name,
            "ticker": raw_ticker,
            "parameters": parameters if isinstance(parameters, dict) else {},
            "status": status,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": cache_key,
            "response_snapshot_id": response_snapshot_id,
            "duration_ms": duration_ms,
            "created_at": _dt_iso(ts),
            "updated_at": _dt_iso(ts),
        }
        finance_requests.append(row)
        return rid

    def _select_authorized_client(api_clients, finance_requests):
        eligible = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not eligible:
            return None, _err("UNAUTHORIZED", "No active API client available to serve this request.")
        one_min_ago = now - datetime.timedelta(minutes=1)
        today = _day_boundary(now)

        for c in eligible:
            rpm_limit = c.get("requests_per_minute_limit")
            day_limit = c.get("requests_per_day_limit")
            if not isinstance(rpm_limit, int) or rpm_limit < 1:
                continue
            if not isinstance(day_limit, int) or day_limit < 1:
                continue
            cday = _dt_parse(c.get("current_day"))
            if cday is None or _day_boundary(cday) != today:
                c["current_day"] = _dt_iso(today)
                c["requests_today"] = 0
                c["updated_at"] = _dt_iso(now)
            req_today = c.get("requests_today")
            if not isinstance(req_today, int) or req_today < 0:
                c["requests_today"] = 0
                req_today = 0
            if req_today >= day_limit:
                continue
            cnt = 0
            for r in finance_requests:
                if r.get("api_client_id") != c.get("id"):
                    continue
                t = _dt_parse(r.get("created_at"))
                if t is None:
                    continue
                if t >= one_min_ago:
                    cnt += 1
                    if cnt >= rpm_limit:
                        break
            if cnt >= rpm_limit:
                continue
            return c, None

        any_day_block = False
        today = _day_boundary(now)
        for c in eligible:
            cday = _dt_parse(c.get("current_day"))
            if cday is None or _day_boundary(cday) != today:
                continue
            req_today = c.get("requests_today")
            if isinstance(req_today, int) and isinstance(c.get("requests_per_day_limit"), int) and req_today >= c.get("requests_per_day_limit"):
                any_day_block = True
                break
        if any_day_block:
            return None, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None, _err("RATE_LIMIT", "Per-minute rate limit exceeded.")

    def _resolve_or_create_security(securities, raw_ticker):
        tnorm = raw_ticker.strip()
        for s in securities:
            if not isinstance(s, dict):
                continue
            st = s.get("ticker")
            if isinstance(st, str) and st.lower() == tnorm.lower():
                return s, False
        sid = _gen_id("sec")
        ts = _dt_iso(now)
        row = {
            "id": sid,
            "ticker": tnorm,
            "exchange": None,
            "quote_type": None,
            "short_name": None,
            "long_name": None,
            "currency": None,
            "country": None,
            "sector": None,
            "industry": None,
            "status": "unknown",
            "created_at": ts,
            "updated_at": ts,
        }
        securities.append(row)
        return row, True

    def _find_snapshot(snapshots, security_id, dataset, params_fingerprint):
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("security_id") == security_id and s.get("dataset") == dataset and s.get("params_fingerprint") == params_fingerprint:
                return s
        return None

    def _snapshot_status_valid(snap):
        if not isinstance(snap, dict):
            return False
        if snap.get("status") != "fresh":
            return False
        exp = _dt_parse(snap.get("expires_at"))
        if exp is None:
            return False
        return exp > now

    def _upsert_snapshot(snapshots, security_id, dataset, params_fingerprint, payload, ttl_seconds=180, as_of=None, status="fresh"):
        if not isinstance(ttl_seconds, int):
            ttl_seconds = 180
        ttl_seconds = max(30, min(2592000, ttl_seconds))
        snap = _find_snapshot(snapshots, security_id, dataset, params_fingerprint)
        ts = _dt_iso(now)
        expires = now + datetime.timedelta(seconds=ttl_seconds)
        if snap is None:
            sid = _gen_id("snap")
            snap = {
                "id": sid,
                "security_id": security_id,
                "dataset": dataset,
                "params_fingerprint": params_fingerprint,
                "source": "yahoo_finance",
                "status": status,
                "as_of": _dt_iso(as_of) if as_of else None,
                "ttl_seconds": ttl_seconds,
                "expires_at": _dt_iso(expires),
                "payload": payload,
                "payload_schema_version": 1,
                "upstream_etag": None,
                "upstream_fetched_at": ts,
                "created_at": ts,
                "updated_at": ts,
            }
            snapshots.append(snap)
        else:
            allowed = {
                "fresh": {"stale", "expired", "error"},
                "stale": {"fresh", "expired", "error"},
                "expired": {"fresh", "error"},
                "error": {"fresh", "expired"},
            }
            cur = snap.get("status")
            if cur in allowed and status != cur and status not in allowed[cur]:
                status = "error"
            snap["status"] = status
            snap["as_of"] = _dt_iso(as_of) if as_of else snap.get("as_of")
            snap["ttl_seconds"] = ttl_seconds
            snap["expires_at"] = _dt_iso(expires)
            snap["payload"] = payload
            snap["payload_schema_version"] = max(1, int(snap.get("payload_schema_version") or 1))
            snap["upstream_fetched_at"] = ts
            snap["updated_at"] = ts
        return snap

    def _synthetic_upstream_news(security):
        t = (security.get("ticker") or "").strip()
        tl = t.lower()
        if tl.endswith(".invalid") or "invalid" in tl or tl in {"", "null"}:
            return {"ok": False, "reason": "invalid"}
        if "delist" in tl or tl.endswith(".delisted"):
            return {"ok": False, "reason": "delisted"}
        items = []
        base = abs(hash((tl, "news"))) % 100000
        for i in range(10):
            published = now - datetime.timedelta(hours=i * 6)
            nid = hashlib.sha256(f"{tl}:{base}:{i}".encode()).hexdigest()[:20]
            items.append({
                "id": nid,
                "title": f"{t} News Item {i+1}",
                "publisher": "Yahoo Finance (offline)",
                "link": f"https://finance.yahoo.com/news/{nid}",
                "published_at": _dt_iso(published),
                "relatedTickers": [t],
                "summary": f"Synthetic news for {t} generated offline.",
            })
        return {"ok": True, "payload": items, "as_of": now}

    if not isinstance(ticker, str) or not ticker.strip():
        api_clients = _load("api_clients.json")
        finance_requests = _load("finance_requests.json")
        client = None
        for c in api_clients:
            if isinstance(c, dict):
                client = c
                break
        if client:
            duration_ms = int((time.time() - start_ts) * 1000)
            _log_request(finance_requests, client.get("id"), None, "get_yahoo_finance_news", ticker if isinstance(ticker, str) else "", {}, "failed", 400, "VALIDATION_ERROR", "ticker must be a non-empty string.", None, None, duration_ms)
            _save("finance_requests.json", finance_requests)
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string.")

    api_clients = _load("api_clients.json")
    securities = _load("securities.json")
    finance_requests = _load("finance_requests.json")
    finance_snapshots = _load("finance_snapshots.json")

    client, auth_err = _select_authorized_client(api_clients, finance_requests)
    if client is None:
