        sec["updated_at"] = _dt_iso(now)

    duration_ms = int((time.time() - start_ts) * 1000)
    _log_request(finance_requests, client["id"], sec["id"], "get_stock_actions", ticker, {}, "fetched_from_yahoo", 200, None, None, cache_key, snap.get("id"), duration_ms)
