def get_recommendations(ticker, recommendation_type, months_back=None, **_extra):
    import json, os, datetime, hashlib, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")
    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None
    def _day_boundary(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        ts = int(_now().timestamp() * 1000)
        rnd = "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(8))
        return f"{prefix}_{ts}_{rnd}"

    def _hash_api_key(plain):
        return hashlib.sha256(plain.encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(ticker, str) or not ticker.strip():
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string")
    if not isinstance(recommendation_type, str) or not recommendation_type.strip():
        return _err("VALIDATION_ERROR", "recommendation_type must be a non-empty string")
    if months_back is None:
        months_back = 12
    if not isinstance(months_back, int):
        return _err("VALIDATION_ERROR", "months_back must be an integer")
    if months_back < 1 or months_back > 60:
        # Must be logged as failed with http 400; but this tool carries no explicit credential.
        # Resolve an ambient active client for logging and quota enforcement.
        pass

    tool_name = "get_recommendations"
    dataset = "recommendations"

    api_clients = _load("api_clients.json")
    securities = _load("securities.json")
    finance_requests = _load("finance_requests.json")
    snapshots = _load("finance_snapshots.json")

    # Resolve ambient authenticated client: pick an active client with room in quota/rate
    # Apply daily reset logic per client.
    now = _now()
    now_day = _day_boundary(now)

    # Compute per-minute counts from finance_requests (rolling 60s)
    window_start = now - datetime.timedelta(seconds=60)
    def _req_time(r):
        return _parse_dt(r.get("created_at"))

    # Prepare per-client recent counts
    recent_counts = {}
    today_counts = {}
    for r in finance_requests:
        cid = r.get("api_client_id")
        if not cid:
            continue
        rt = _req_time(r)
        if not rt:
            continue
        if rt >= window_start:
            recent_counts[cid] = recent_counts.get(cid, 0) + 1
        if rt >= now_day:
            today_counts[cid] = today_counts.get(cid, 0) + 1

    chosen_client = None
    for c in api_clients:
        if c.get("status") != "active":
            continue
        # normalize/reset current_day
        c_day = _parse_dt(c.get("current_day"))
        if not c_day or _day_boundary(c_day) != now_day:
            c["current_day"] = _iso(now_day)
            c["requests_today"] = 0
            c["updated_at"] = _iso(now)
        # enforce limits based on stored counters + observed logs (use max to be safe)
        stored_today = c.get("requests_today")
        if not isinstance(stored_today, int) or stored_today < 0:
            stored_today = 0
        observed_today = today_counts.get(c.get("id"), 0)
        effective_today = max(stored_today, observed_today)

        rpm_limit = c.get("requests_per_minute_limit")
        rpd_limit = c.get("requests_per_day_limit")
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            continue
        if not isinstance(rpd_limit, int) or rpd_limit < 1:
            continue

        recent = recent_counts.get(c.get("id"), 0)
        if effective_today >= rpd_limit:
            continue
        if recent >= rpm_limit:
            continue
        chosen_client = c
        break

    if chosen_client is None:
        # No ambient client can serve; must be UNAUTHORIZED per contract for missing auth context
        # (even though no api_key param is present).
        return _err("UNAUTHORIZED", "No active API client available to serve this request")

    # Resolve/create security by case-insensitive ticker match
    raw_ticker = ticker
    norm = ticker.strip()
    if len(norm) < 1 or len(norm) > 16:
        # still must log failed with 400
        sec = None
    else:
        sec = None
        norm_l = norm.lower()
        for s in securities:
            t = s.get("ticker")
            if isinstance(t, str) and t.lower() == norm_l:
                sec = s
                break
        if sec is None:
            sec = {
                "id": _gen_id("sec"),
                "ticker": norm,
                "exchange": None,
                "quote_type": None,
                "short_name": None,
                "long_name": None,
                "currency": None,
                "country": None,
                "sector": None,
                "industry": None,
                "status": "unknown",
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            securities.append(sec)
            _save("securities.json", securities)

    # Prepare finance_requests row (exactly one per invocation)
    params = {
        "ticker": raw_ticker,
        "recommendation_type": recommendation_type,
        "months_back": months_back,
    }

    fr = {
        "id": _gen_id("req"),
        "api_client_id": chosen_client.get("id"),
        "security_id": sec.get("id") if sec else None,
        "tool_name": tool_name,
        "ticker": raw_ticker,
        "parameters": params,
        "status": "received",
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "cache_key": None,
        "response_snapshot_id": None,
        "duration_ms": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    start = time.time()

    # Rate/quota enforcement (reject and log with 429)
    # Refresh effective counters for chosen client after potential daily reset.
    rpm_limit = chosen_client.get("requests_per_minute_limit")
    rpd_limit = chosen_client.get("requests_per_day_limit")
    client_id = chosen_client.get("id")

    stored_today = chosen_client.get("requests_today") if isinstance(chosen_client.get("requests_today"), int) else 0
    observed_today = today_counts.get(client_id, 0)
    effective_today = max(stored_today, observed_today)
    recent = recent_counts.get(client_id, 0)

    def _finalize_failed(code, msg, http_status):
        fr["status"] = "failed"
        fr["http_status_code"] = http_status
        fr["error_code"] = code
        fr["error_message"] = msg
        fr["updated_at"] = _iso(_now())
        fr["duration_ms"] = max(0, int((time.time() - start) * 1000))
        finance_requests.append(fr)
        _save("finance_requests.json", finance_requests)
        return _err(code, msg, http_status=http_status)

    if chosen_client.get("status") != "active":
        return _finalize_failed("UNAUTHORIZED", "API client is not active", 429)
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or not isinstance(rpd_limit, int) or rpd_limit < 1:
        return _finalize_failed("UNAUTHORIZED", "API client limits are misconfigured", 429)
    if effective_today >= rpd_limit:
        return _finalize_failed("QUOTA_EXCEEDED", "Daily request quota exceeded", 429)
    if recent >= rpm_limit:
        return _finalize_failed("RATE_LIMIT", "Per-minute rate limit exceeded", 429)

    # Dataset-specific validation
    if len(norm) < 1 or len(norm) > 16:
        return _finalize_failed("VALIDATION_ERROR", "ticker length must be between 1 and 16", 400)
    if not isinstance(months_back, int) or months_back < 1 or months_back > 60:
        return _finalize_failed("VALIDATION_ERROR", "months_back must be between 1 and 60 (inclusive)", 400)

    # Compute params_fingerprint (recommendation_type, months_back)
    fp_src = json.dumps({"recommendation_type": recommendation_type, "months_back": months_back}, sort_keys=True, separators=(",", ":"))
    params_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    # Cache lookup
    cache_key = f"{dataset}:{sec['id']}:{params_fingerprint}"
    fr["cache_key"] = cache_key

    snap = None
    for ss in snapshots:
        if ss.get("security_id") == sec["id"] and ss.get("dataset") == dataset and ss.get("params_fingerprint") == params_fingerprint:
            snap = ss
            break

    now2 = _now()
    if snap:
        exp = _parse_dt(snap.get("expires_at"))
        if snap.get("status") == "fresh" and exp and exp > now2 and snap.get("payload") is not None:
            fr["status"] = "served_from_cache"
            fr["http_status_code"] = 200
            fr["response_snapshot_id"] = snap.get("id")
            fr["updated_at"] = _iso(now2)
            fr["duration_ms"] = max(0, int((time.time() - start) * 1000))
            finance_requests.append(fr)
            _save("finance_requests.json", finance_requests)

            # Update client counters
            chosen_client["requests_today"] = effective_today + 1
            chosen_client["updated_at"] = _iso(_now())
            _save("api_clients.json", api_clients)

            return {
                "data": snap.get("payload"),
                "meta": {
                    "ticker": raw_ticker,
                    "security_id": sec["id"],
                    "served_from": "cache",
                    "snapshot_id": snap.get("id"),
                },
            }

    # "Fetch upstream" offline: synthesize deterministic payload and upsert snapshot.
    # If security is delisted/inactive, treat as invalid upstream.
    if sec.get("status") == "delisted":
        # Transition not allowed from delisted; just fail.
        return _finalize_failed("NOT_FOUND", "Ticker is delisted", 404)

    # Create deterministic faux payload based on ticker+params (not fabricated rows beyond snapshot payload)
    seed = hashlib.sha256((norm.lower() + "|" + recommendation_type + "|" + str(months_back)).encode("utf-8")).hexdigest()
    as_of = _now()
    payload = {
        "ticker": norm.upper(),
        "recommendation_type": recommendation_type,
        "months_back": months_back,
        "as_of": _iso(as_of),
        "items": [
            {
                "event_id": seed[:12],
                "date": _iso(as_of - datetime.timedelta(days=7)),
                "firm": "Example Research",
                "to_grade": "Buy",
                "from_grade": "Hold",
                "action": "up",
            }
        ],
    }

    ttl_seconds = 6 * 60 * 60  # 6h within allowed range
    expires_at = as_of + datetime.timedelta(seconds=ttl_seconds)

    if snap is None:
        snap = {
            "id": _gen_id("snap"),
            "security_id": sec["id"],
            "dataset": dataset,
            "params_fingerprint": params_fingerprint,
            "source": "yahoo_finance",
            "status": "fresh",
            "as_of": _iso(as_of),
            "ttl_seconds": ttl_seconds,
            "expires_at": _iso(expires_at),
            "payload": payload,
            "payload_schema_version": 1,
            "upstream_etag": None,
            "upstream_fetched_at": _iso(as_of),
            "created_at": _iso(as_of),
            "updated_at": _iso(as_of),
        }
        snapshots.append(snap)
    else:
        # legal transitions: expired/error/stale -> fresh; fresh can stay fresh by overwriting without transition
        snap["status"] = "fresh"
        snap["as_of"] = _iso(as_of)
        snap["ttl_seconds"] = ttl_seconds
        snap["expires_at"] = _iso(expires_at)
        snap["payload"] = payload
        snap["payload_schema_version"] = max(1, int(snap.get("payload_schema_version") or 1))
        snap["upstream_fetched_at"] = _iso(as_of)
        snap["updated_at"] = _iso(as_of)

    _save("finance_snapshots.json", snapshots)

    fr["status"] = "fetched_from_yahoo"
    fr["http_status_code"] = 200
    fr["response_snapshot_id"] = snap.get("id")
    fr["updated_at"] = _iso(_now())
    fr["duration_ms"] = max(0, int((time.time() - start) * 1000))
    finance_requests.append(fr)
    _save("finance_requests.json", finance_requests)

    # Update client counters
    chosen_client["requests_today"] = effective_today + 1
    chosen_client["updated_at"] = _iso(_now())
    _save("api_clients.json", api_clients)

    return {
        "data": payload,
        "meta": {
            "ticker": raw_ticker,
            "security_id": sec["id"],
            "served_from": "upstream",
            "snapshot_id": snap.get("id"),
        },
    }

def get_current_api_client(api_key, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")
    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None
    def _day_boundary(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _hash_api_key(plain):
        return hashlib.sha256(plain.encode("utf-8")).hexdigest()

    start = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_clients = _load("api_clients.json")
    finance_requests = _load("finance_requests.json")

    key = api_key.strip()
    key_hash = _hash_api_key(key)

    client = None
    for c in api_clients:
        if c.get("id") == key or c.get("api_key_hash") == key or c.get("api_key_hash") == key_hash:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    now = _now()
    now_day = _day_boundary(now)
    c_day = _parse_dt(client.get("current_day"))
    if not c_day or _day_boundary(c_day) != now_day:
        client["current_day"] = _iso(now_day)
        client["requests_today"] = 0
        client["updated_at"] = _iso(now)
        _save("api_clients.json", api_clients)

    # Compute today's usage from logs too; use max as effective
    window_start = now - datetime.timedelta(seconds=60)
    today_start = now_day
    recent = 0
    today = 0
    for r in finance_requests:
        if r.get("api_client_id") != client.get("id"):
            continue
        rt = _parse_dt(r.get("created_at"))
        if not rt:
            continue
        if rt >= window_start:
            recent += 1
        if rt >= today_start:
            today += 1

    stored_today = client.get("requests_today") if isinstance(client.get("requests_today"), int) else 0
    effective_today = max(stored_today, today)

    rpm_limit = client.get("requests_per_minute_limit")
    rpd_limit = client.get("requests_per_day_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or not isinstance(rpd_limit, int) or rpd_limit < 1:
        return _err("UNAUTHORIZED", "Client limits are misconfigured")

    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active", status=client.get("status"))

    if effective_today >= rpd_limit:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", http_status=429)

    if recent >= rpm_limit:
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded", http_status=429)

    # Log this call as a finance_requests row too (tool not in enum, so we cannot per schema).
    # The enum constraint for finance_requests.tool_name excludes this endpoint. Therefore we
    # must not write an invalid row; instead, we only update counters based on existing schema.
    # (No compliant place to log within declared collections.)

    # Return identity + limits + counters
    return {
        "data": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "requests_per_minute_limit": rpm_limit,
            "requests_per_day_limit": rpd_limit,
            "current_day": client.get("current_day"),
            "requests_today": effective_today,
            "requests_last_minute": recent,
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "meta": {
            "latency_ms": max(0, int((time.time() - start) * 1000))
        },
    }

def list_securities(api_key, ticker=None, exchange=None, status=None, quote_type=None, page=None, page_size=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")
    def _day_boundary(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
    def _hash_api_key(plain):
        return hashlib.sha256(plain.encode("utf-8")).hexdigest()

    start = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    if status is not None:
        if not isinstance(status, str) or status not in {"active", "inactive", "delisted", "unknown"}:
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, delisted, unknown")

    api_clients = _load("api_clients.json")
    finance_requests = _load("finance_requests.json")
    securities = _load("securities.json")

    key = api_key.strip()
    key_hash = _hash_api_key(key)

    client = None
    for c in api_clients:
        if c.get("id") == key or c.get("api_key_hash") == key or c.get("api_key_hash") == key_hash:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    now = _now()
    now_day = _day_boundary(now)
    c_day = _parse_dt(client.get("current_day"))
    if not c_day or _day_boundary(c_day) != now_day:
        client["current_day"] = _iso(now_day)
        client["requests_today"] = 0
        client["updated_at"] = _iso(now)
        _save("api_clients.json", api_clients)

    # Enforce rate/quota (read included) based on logs in last minute / today.
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    today = 0
    for r in finance_requests:
        if r.get("api_client_id") != client.get("id"):
            continue
        rt = _parse_dt(r.get("created_at"))
        if not rt:
            continue
        if rt >= window_start:
            recent += 1
        if rt >= now_day:
            today += 1

    stored_today = client.get("requests_today") if isinstance(client.get("requests_today"), int) else 0
    effective_today = max(stored_today, today)

    rpm_limit = client.get("requests_per_minute_limit")
    rpd_limit = client.get("requests_per_day_limit")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active", http_status=429)
    if effective_today >= rpd_limit:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", http_status=429)
    if recent >= rpm_limit:
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded", http_status=429)

    # Cannot log this call in finance_requests due to tool_name enum mismatch; avoid invalid writes.

    # Filtering
    out = []
    ticker_l = ticker.lower() if isinstance(ticker, str) and ticker.strip() else None
    for s in securities:
        if ticker_l is not None:
            t = s.get("ticker")
            if not isinstance(t, str) or t.lower() != ticker_l:
                continue
        if exchange is not None:
            if not isinstance(exchange, str):
                return _err("VALIDATION_ERROR", "exchange must be a string")
            if s.get("exchange") != exchange:
                continue
        if status is not None:
            if s.get("status") != status:
                continue
        if quote_type is not None:
            if not isinstance(quote_type, str):
                return _err("VALIDATION_ERROR", "quote_type must be a string")
            if s.get("quote_type") != quote_type:
                continue
        out.append(s)

    # Sort by ticker then id for stability
    def _k(row):
        t = row.get("ticker")
        return ((t or "").lower(), row.get("id") or "")
    out.sort(key=_k)

    total = len(out)
    start_i = (page - 1) * page_size
    end_i = start_i + page_size
    items = out[start_i:end_i]
    has_more = end_i < total

    # Update client counters (reads count)
    client["requests_today"] = effective_today + 1
    client["updated_at"] = _iso(_now())
    _save("api_clients.json", api_clients)

    return {
        "data": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "latency_ms": max(0, int((time.time() - start) * 1000)),
        },
    }

