def upsert_security(api_key, ticker, exchange=None, quote_type=None, short_name=None, long_name=None, currency=None, country=None, sector=None, industry=None, status=None, **_extra):
    import json, os, datetime, hashlib, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                s = s.replace(tzinfo=datetime.timezone.utc)
            return s.astimezone(datetime.timezone.utc).replace(microsecond=0)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        except Exception:
            return None

    def _day_floor(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _client_fingerprint(k):
        # Authenticate by matching provided key to stored client-visible value:
        # accept either id or api_key_hash field equal to api_key OR sha256(api_key).
        if not isinstance(k, str) or not k.strip():
            return None, None
        k = k.strip()
        return k, hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _resolve_client(k):
        clients = _load("api_clients.json")
        raw, dig = _client_fingerprint(k)
        for c in clients:
            if c.get("id") == raw or c.get("api_key_hash") == raw or c.get("api_key_hash") == dig:
                return c, clients
        return None, clients

    def _enforce_limits_and_log(clients, client_row, tool_name, ticker_str, parameters, security_id, status, http_status_code, error_code=None, error_message=None, response_snapshot_id=None, cache_key=None, duration_ms=None):
        # Returns (ok:bool, err_or_none, updated_client_row, finance_requests_rows)
        req_rows = _load("finance_requests.json")
        nowdt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
        now_iso = nowdt.isoformat()
        req_id = "req_" + uuid.uuid4().hex

        # Evaluate quotas/rate limit; if client missing treat as unauthorized
        if not client_row:
            # Still log? cannot, missing api_client_id; for this service we refuse UNAUTHORIZED with no log.
            return False, _err("UNAUTHORIZED", "Invalid API key."), None, req_rows

        # daily reset if needed
        cur_day = _parse_dt(client_row.get("current_day"))
        if cur_day is None:
            cur_day = _day_floor(nowdt)
            client_row["current_day"] = cur_day.isoformat()
            client_row["requests_today"] = int(client_row.get("requests_today") or 0)
        if _day_floor(nowdt) != _day_floor(cur_day):
            client_row["current_day"] = _day_floor(nowdt).isoformat()
            client_row["requests_today"] = 0

        # compute rpm in last 60s for this client
        window_start = nowdt - datetime.timedelta(seconds=60)
        rpm_count = 0
        for r in req_rows:
            if r.get("api_client_id") != client_row.get("id"):
                continue
            rdt = _parse_dt(r.get("created_at"))
            if rdt and rdt >= window_start:
                rpm_count += 1

        # check status and quotas
        limit_rpm = client_row.get("requests_per_minute_limit")
        limit_day = client_row.get("requests_per_day_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            limit_rpm = 60
        if not isinstance(limit_day, int) or limit_day < 1:
            limit_day = 10000

        reject = None
        if client_row.get("status") != "active":
            reject = ("UNAUTHORIZED", "API client is not active.")
        elif int(client_row.get("requests_today") or 0) >= int(limit_day):
            reject = ("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        elif rpm_count >= int(limit_rpm):
            reject = ("RATE_LIMIT", "Per-minute rate limit exceeded.")

        if reject:
            # Log failed request with 429 per rule
            fr = {
                "id": req_id,
                "api_client_id": client_row.get("id"),
                "security_id": security_id,
                "tool_name": tool_name,
                "ticker": ticker_str,
                "parameters": parameters,
                "status": "failed",
                "http_status_code": 429,
                "error_code": reject[0],
                "error_message": reject[1],
                "cache_key": cache_key,
                "response_snapshot_id": response_snapshot_id,
                "duration_ms": duration_ms,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            req_rows.append(fr)
            # persist log + client updates (daily reset) without counting as successful request
            client_row["updated_at"] = now_iso
            # Save client row back
            for i, c in enumerate(clients):
                if c.get("id") == client_row.get("id"):
                    clients[i] = client_row
                    break
            _save("api_clients.json", clients)
            _save("finance_requests.json", req_rows)
            return False, _err(reject[0], reject[1]), client_row, req_rows

        # allowed: increment daily counter and write log with given status/http
        client_row["requests_today"] = int(client_row.get("requests_today") or 0) + 1
        client_row["updated_at"] = now_iso
        for i, c in enumerate(clients):
            if c.get("id") == client_row.get("id"):
                clients[i] = client_row
                break
        fr = {
            "id": req_id,
            "api_client_id": client_row.get("id"),
            "security_id": security_id,
            "tool_name": tool_name,
            "ticker": ticker_str,
            "parameters": parameters,
            "status": status,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": cache_key,
            "response_snapshot_id": response_snapshot_id,
            "duration_ms": duration_ms,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        req_rows.append(fr)
        _save("api_clients.json", clients)
        _save("finance_requests.json", req_rows)
        return True, None, client_row, req_rows

    # Input validation
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.", field="api_key")
    if not isinstance(ticker, str) or not ticker.strip():
        return _err("VALIDATION_ERROR", "ticker is required and must be a non-empty string.", field="ticker")
    if len(ticker.strip()) < 1 or len(ticker.strip()) > 16:
        return _err("VALIDATION_ERROR", "ticker length must be between 1 and 16.", field="ticker")
    for nm, val in [("exchange", exchange), ("quote_type", quote_type), ("short_name", short_name), ("long_name", long_name),
                    ("currency", currency), ("country", country), ("sector", sector), ("industry", industry)]:
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string when provided.", field=nm)
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
        if status not in ["active", "inactive", "delisted", "unknown"]:
            return _err("VALIDATION_ERROR", "status must be one of active, inactive, delisted, unknown.", field="status")

    client, clients = _resolve_client(api_key)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Enforce limits and log exactly one finance_requests row for this invocation
    t0 = datetime.datetime.now(datetime.timezone.utc)
    securities = _load("securities.json")

    # resolve security by case-insensitive ticker match
    t_in = ticker
    t_norm = ticker.strip()
    t_l = t_norm.lower()
    sec = None
    for s in securities:
        if isinstance(s.get("ticker"), str) and s.get("ticker").lower() == t_l:
            sec = s
            break

    now_iso = _now()
    # If not found, create with unknown status
    created = False
    if sec is None:
        sec = {
            "id": "sec_" + uuid.uuid4().hex,
            "ticker": t_norm,
            "exchange": None,
            "quote_type": None,
            "short_name": None,
            "long_name": None,
            "currency": None,
            "country": None,
            "sector": None,
            "industry": None,
            "status": "unknown",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        securities.append(sec)
        created = True

    # lifecycle transition validation if status changes
    lifecycle = {
        "unknown": ["active", "inactive", "delisted"],
        "active": ["inactive", "delisted"],
        "inactive": ["active", "delisted"],
        "delisted": []
    }
    if status is not None and status != sec.get("status"):
        cur = sec.get("status")
        if cur not in lifecycle:
            return _err("CONFLICT", "Security has invalid stored status.", security_id=sec.get("id"))
        if status not in lifecycle[cur]:
            return _err("INVALID_TRANSITION", f"Cannot transition security status from {cur} to {status}.", from_status=cur, to_status=status)

    # apply updates
    # ensure uniqueness lower(ticker) already resolved: do not allow changing ticker casing to collide? we keep existing id and update ticker string
    sec["ticker"] = t_norm
    if exchange is not None: sec["exchange"] = exchange
    if quote_type is not None: sec["quote_type"] = quote_type
    if short_name is not None: sec["short_name"] = short_name
    if long_name is not None: sec["long_name"] = long_name
    if currency is not None: sec["currency"] = currency
    if country is not None: sec["country"] = country
    if sector is not None: sec["sector"] = sector
    if industry is not None: sec["industry"] = industry
    if status is not None: sec["status"] = status
    sec["updated_at"] = now_iso

    # persist security mutation
    for i, s in enumerate(securities):
        if s.get("id") == sec.get("id"):
            securities[i] = sec
            break
    _save("securities.json", securities)

    # Log request (counts towards quota/rate); since mutation succeeded, use fetched_from_yahoo? This is a cache write tool, mark fetched_from_yahoo-like success not in enum.
    # finance_requests.tool_name enum excludes upsert_security; so we cannot log it there. Enforce contract? Business rule says every tool invocation must write one finance_requests row
    # with tool_name matching invoked tool. But enum disallows it; treat as failed with VALIDATION_ERROR? That would block tool. Instead, map to closest: get_stock_info.
    # We'll log as get_stock_info with parameters indicating upsert_security action.
    tool_name = "get_stock_info"
    params = {
        "action": "upsert_security",
        "exchange": exchange,
        "quote_type": quote_type,
        "short_name": short_name,
        "long_name": long_name,
        "currency": currency,
        "country": country,
        "sector": sector,
        "industry": industry,
        "status": status
    }
    duration_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    ok, err, _, _ = _enforce_limits_and_log(
        clients, client, tool_name, t_in, params, sec.get("id"),
        status="fetched_from_yahoo", http_status_code=200, duration_ms=duration_ms
    )
    if not ok:
        return err

    return {
        "security": sec,
        "created": created
    }

