        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                s = s.replace(tzinfo=datetime.timezone.utc)
            return s.astimezone(datetime.timezone.utc).replace(microsecond=0)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        except Exception:
            return None

    def _day_floor(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _client_fingerprint(k):
        if not isinstance(k, str) or not k.strip():
            return None, None
        k = k.strip()
        return k, hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _resolve_client(k):
        clients = _load("api_clients.json")
        raw, dig = _client_fingerprint(k)
        for c in clients:
            if c.get("id") == raw or c.get("api_key_hash") == raw or c.get("api_key_hash") == dig:
                return c, clients
        return None, clients

    def _enforce_and_log(clients, client_row, tool_name, ticker_str, parameters, security_id, status, http_status_code, error_code=None, error_message=None, response_snapshot_id=None, cache_key=None, duration_ms=None):
        req_rows = _load("finance_requests.json")
        nowdt = _nowdt()
        now_iso = nowdt.isoformat()
        req_id = "req_" + uuid.uuid4().hex

        if not client_row:
            return False, _err("UNAUTHORIZED", "Invalid API key."), None, req_rows

        cur_day = _parse_dt(client_row.get("current_day"))
        if cur_day is None:
            cur_day = _day_floor(nowdt)
            client_row["current_day"] = cur_day.isoformat()
            client_row["requests_today"] = int(client_row.get("requests_today") or 0)
        if _day_floor(nowdt) != _day_floor(cur_day):
            client_row["current_day"] = _day_floor(nowdt).isoformat()
            client_row["requests_today"] = 0

        window_start = nowdt - datetime.timedelta(seconds=60)
        rpm_count = 0
        for r in req_rows:
            if r.get("api_client_id") != client_row.get("id"):
                continue
            rdt = _parse_dt(r.get("created_at"))
            if rdt and rdt >= window_start:
                rpm_count += 1

        limit_rpm = client_row.get("requests_per_minute_limit")
        limit_day = client_row.get("requests_per_day_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            limit_rpm = 60
        if not isinstance(limit_day, int) or limit_day < 1:
            limit_day = 10000

        reject = None
        if client_row.get("status") != "active":
            reject = ("UNAUTHORIZED", "API client is not active.")
        elif int(client_row.get("requests_today") or 0) >= int(limit_day):
            reject = ("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        elif rpm_count >= int(limit_rpm):
            reject = ("RATE_LIMIT", "Per-minute rate limit exceeded.")

        if reject:
            fr = {
                "id": req_id,
                "api_client_id": client_row.get("id"),
                "security_id": security_id,
                "tool_name": tool_name,
                "ticker": ticker_str,
                "parameters": parameters,
                "status": "failed",
                "http_status_code": 429,
                "error_code": reject[0],
                "error_message": reject[1],
                "cache_key": cache_key,
                "response_snapshot_id": response_snapshot_id,
                "duration_ms": duration_ms,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            req_rows.append(fr)
            client_row["updated_at"] = now_iso
            for i, c in enumerate(clients):
                if c.get("id") == client_row.get("id"):
                    clients[i] = client_row
                    break
            _save("api_clients.json", clients)
            _save("finance_requests.json", req_rows)
            return False, _err(reject[0], reject[1]), client_row, req_rows

        client_row["requests_today"] = int(client_row.get("requests_today") or 0) + 1
        client_row["updated_at"] = now_iso
        for i, c in enumerate(clients):
            if c.get("id") == client_row.get("id"):
                clients[i] = client_row
                break
        fr = {
            "id": req_id,
            "api_client_id": client_row.get("id"),
            "security_id": security_id,
            "tool_name": tool_name,
            "ticker": ticker_str,
            "parameters": parameters,
            "status": status,
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": cache_key,
            "response_snapshot_id": response_snapshot_id,
            "duration_ms": duration_ms,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        req_rows.append(fr)
        _save("api_clients.json", clients)
        _save("finance_requests.json", req_rows)
        return True, None, client_row, req_rows

    def _fingerprint_for(dataset_name, params):
        # Deterministic: sorted json with stable separators, then sha256.
        stable = json.dumps(params, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(stable.encode("utf-8")).hexdigest()

    def _dataset_to_toolname(ds):
        m = {
            "historical_prices": "get_historical_stock_prices",
            "stock_info": "get_stock_info",
            "news": "get_yahoo_finance_news",
            "actions": "get_stock_actions",
            "financial_statement": "get_financial_statement",
            "holder_info": "get_holder_info",
            "option_expiration_dates": "get_option_expiration_dates",
            "option_chain": "get_option_chain",
            "recommendations": "get_recommendations",
        }
        return m.get(ds)

    def _ttl_for(ds):
        # Reasonable TTL defaults within allowed range.
        return {
            "historical_prices": 300,
            "stock_info": 900,
            "news": 300,
            "actions": 3600,
            "financial_statement": 86400,
            "holder_info": 86400,
            "options_expiration_dates": 3600,
            "option_chain": 900,
            "recommendations": 86400,
        }.get(ds, 900)

    def _validate_rfc3339_date(d):
        if not isinstance(d, str):
            return False
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", d):
            return False
        try:
            datetime.date.fromisoformat(d)
            return True
        except Exception:
            return False

    def _upstream_fetch(security_row, ds, params):
        # Offline simulation with deterministic payload; also mark invalid/delisted for clearly invalid tickers.
        t = security_row.get("ticker") or ""
        t_up = str(t).upper()
        if not re.fullmatch(r"[A-Z0-9.\-^=]{1,16}", t_up):
            return {"ok": False, "not_found": True, "message": "Ticker not found."}
        if any(x in t_up for x in ["DELIST", "DELST", "DELISTED"]):
            return {"ok": False, "delisted": True, "message": "Ticker is delisted."}

        now = _nowdt()
        payload = {"ticker": t_up, "dataset": ds, "params": params, "as_of": now.isoformat()}
        if ds == "stock_info":
            payload["info"] = {"shortName": security_row.get("short_name") or t_up, "currency": security_row.get("currency") or "USD"}
        elif ds == "news":
            payload["items"] = [{"id": "n1", "title": f"{t_up} headline", "published_at": now.isoformat()}]
        elif ds == "actions":
            payload["actions"] = []
        elif ds == "financial_statement":
            payload["statement"] = {"type": params.get("financial_type"), "rows": []}
        elif ds == "holder_info":
            payload["holders"] = {"type": params.get("holder_type"), "rows": []}
        elif ds == "options_expiration_dates":
            payload["expiration_dates"] = [(now.date() + datetime.timedelta(days=7)).isoformat()]
        elif ds == "option_chain":
            payload["chain"] = {"expiration_date": params.get("expiration_date"), "option_type": params.get("option_type"), "contracts": []}
        elif ds == "recommendations":
            payload["recommendations"] = {"type": params.get("recommendation_type"), "months_back": params.get("months_back"), "items": []}
        elif ds == "historical_prices":
            # generate small set of bars
            interval_val = params.get("interval")
            bars = []
            for i in range(5):
                bt = (now - datetime.timedelta(days=5 - i)).replace(hour=0, minute=0, second=0, microsecond=0)
                base = 100.0 + i
                bars.append({
                    "bar_time": bt.isoformat(),
                    "open": base,
                    "high": base + 1.0,
                    "low": base - 1.0,
                    "close": base + 0.5,
                    "adj_close": base + 0.4,
                    "volume": 1000000 + i * 1000,
                    "interval": interval_val
                })
            payload["bars"] = bars
        return {"ok": True, "payload": payload, "as_of": now.isoformat(), "etag": hashlib.sha256(json.dumps(payload, sort_keys=True).encode("utf-8")).hexdigest()}

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.", field="api_key")
    if not isinstance(ticker, str) or not ticker.strip():
        return _err("VALIDATION_ERROR", "ticker is required and must be a non-empty string.", field="ticker")
    if len(ticker.strip()) < 1 or len(ticker.strip()) > 16:
        return _err("VALIDATION_ERROR", "ticker length must be between 1 and 16.", field="ticker")
    if not isinstance(dataset, str):
        return _err("VALIDATION_ERROR", "dataset is required and must be a string.", field="dataset")
    allowed_datasets = ["stock_info", "historical_prices", "news", "actions", "financial_statement", "holder_info", "option_expiration_dates", "option_chain", "recommendations"]
    if dataset not in allowed_datasets:
        return _err("VALIDATION_ERROR", "Unsupported dataset.", field="dataset", allowed=allowed_datasets)
    if include_payload is None:
        include_payload = False
    if not isinstance(include_payload, bool):
        return _err("VALIDATION_ERROR", "include_payload must be boolean when provided.", field="include_payload")

    # dataset-specific validation and fingerprint params per rules
    fp_params = {}
    req_params = {"dataset": dataset}
    if dataset == "historical_prices":
        allowed_period = {"1d","5d","1mo","3mo","6mo","1y","2y","5y","10y","ytd","max"}
        allowed_interval = {"1m","2m","5m","15m","30m","60m","90m","1h","1d","5d","1wk","1mo","3mo"}
        if period is None or not isinstance(period, str) or period not in allowed_period:
            return _err("VALIDATION_ERROR", "period is required for historical_prices and must be a supported value.", field="period")
        if interval is None or not isinstance(interval, str) or interval not in allowed_interval:
            return _err("VALIDATION_ERROR", "interval is required for historical_prices and must be a supported value.", field="interval")
        fp_params = {"period": period, "interval": interval}
        req_params.update(fp_params)
    elif dataset == "financial_statement":
        allowed = {"income_stmt","quarterly_income_stmt","balance_sheet","quarterly_balance_sheet","cashflow","quarterly_cashflow"}
        if financial_type is None or not isinstance(financial_type, str) or financial_type not in allowed:
            return _err("VALIDATION_ERROR", "financial_type is required for financial_statement and must be supported.", field="financial_type")
        fp_params = {"financial_type": financial_type}
        req_params.update(fp_params)
    elif dataset == "holder_info":
        allowed = {"major_holders","institutional_holders","mutualfund_holders","insider_transactions","insider_purchases","insider_roster_holders"}
        if holder_type is None or not isinstance(holder_type, str) or holder_type not in allowed:
            return _err("VALIDATION_ERROR", "holder_type is required for holder_info and must be supported.", field="holder_type")
        fp_params = {"holder_type": holder_type}
        req_params.update(fp_params)
    elif dataset == "option_chain":
        if expiration_date is None or not _validate_rfc3339_date(expiration_date):
            return _err("VALIDATION_ERROR", "expiration_date is required for option_chain and must be YYYY-MM-DD.", field="expiration_date")
        if option_type is None or not isinstance(option_type, str) or option_type not in {"calls","puts"}:
            return _err("VALIDATION_ERROR", "option_type is required for option_chain and must be 'calls' or 'puts'.", field="option_type")
        fp_params = {"expiration_date": expiration_date, "option_type": option_type}
        req_params.update(fp_params)
    elif dataset == "recommendations":
        if months_back is None:
            months_back = 12
        if not isinstance(months_back, int) or months_back < 1 or months_back > 60:
            return _err("VALIDATION_ERROR", "months_back must be an integer between 1 and 60.", field="months_back")
        if recommendation_type is not None and not isinstance(recommendation_type, str):
            return _err("VALIDATION_ERROR", "recommendation_type must be a string when provided.", field="recommendation_type")
        fp_params = {"recommendation_type": recommendation_type, "months_back": months_back}
        req_params.update(fp_params)
    else:
        fp_params = {"default": True}
        # still store provided optional params? keep minimal
        req_params["params"] = "default"

    # Resolve client
    client, clients = _resolve_client(api_key)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key.")

    t0 = _nowdt()
    # Resolve/create security
    securities = _load("securities.json")
    t_in = ticker
    t_norm = ticker.strip()
    t_l = t_norm.lower()
    sec = None
    for s in securities:
        if isinstance(s.get("ticker"), str) and s.get("ticker").lower() == t_l:
            sec = s
            break
    now_iso = _now()
    if sec is None:
        sec = {
            "id": "sec_" + uuid.uuid4().hex,
            "ticker": t_norm,
            "exchange": None,
            "quote_type": None,
            "short_name": None,
            "long_name": None,
            "currency": None,
            "country": None,
            "sector": None,
            "industry": None,
            "status": "unknown",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        securities.append(sec)
        _save("securities.json", securities)

    # Fetch upstream (forced refresh, bypass cache)
    upstream = _upstream_fetch(sec, dataset, fp_params)
    duration_ms = int((_nowdt() - t0).total_seconds() * 1000)
    tool_name = _dataset_to_toolname(dataset)
    if tool_name is None:
        # should never happen because validated dataset
        ok, err, _, _ = _enforce_and_log(clients, client, "get_stock_info", t_in, req_params, sec.get("id"),
                                         status="failed", http_status_code=400, error_code="VALIDATION_ERROR",
                                         error_message="Unsupported dataset mapping.", duration_ms=duration_ms)
        if not ok:
            return err
        return _err("VALIDATION_ERROR", "Unsupported dataset mapping.")

    if not upstream.get("ok"):
        # Update security status per business rule
        lifecycle = {
            "unknown": ["active", "inactive", "delisted"],
            "active": ["inactive", "delisted"],
            "inactive": ["active", "delisted"],
            "delisted": []
        }
        if upstream.get("delisted"):
            if sec.get("status") != "delisted" and "delisted" in lifecycle.get(sec.get("status"), []):
                sec["status"] = "delisted"
                sec["updated_at"] = now_iso
        elif upstream.get("not_found"):
            # treat as inactive for invalid/unresolved
            if sec.get("status") != "inactive" and "inactive" in lifecycle.get(sec.get("status"), []):
                sec["status"] = "inactive"
                sec["updated_at"] = now_iso
        # persist security update if changed
        for i, s in enumerate(securities):
            if s.get("id") == sec.get("id"):
                securities[i] = sec
                break
        _save("securities.json", securities)

        # log failed request
        ok, err, _, _ = _enforce_and_log(
            clients, client, tool_name, t_in, req_params, sec.get("id"),
            status="failed", http_status_code=404, error_code="NOT_FOUND",
            error_message=upstream.get("message") or "Ticker not found.", duration_ms=duration_ms
        )
        if not ok:
            return err
        return _err("NOT_FOUND", upstream.get("message") or "Ticker not found.", ticker=t_in)

    # Upsert snapshot
    snapshots = _load("finance_snapshots.json")
    params_fingerprint = _fingerprint_for(dataset, fp_params)
    ttl = _ttl_for(dataset)
    nowdt = _nowdt()
    expires_at = (nowdt + datetime.timedelta(seconds=ttl)).isoformat()
    snap = None
    for s in snapshots:
        if s.get("security_id") == sec.get("id") and s.get("dataset") == dataset and s.get("params_fingerprint") == params_fingerprint:
            snap = s
            break
    payload = upstream.get("payload")
    snap_id = None
    if snap is None:
        snap_id = "snap_" + uuid.uuid4().hex
        snap = {
            "id": snap_id,
            "security_id": sec.get("id"),
            "dataset": dataset,
            "params_fingerprint": params_fingerprint,
            "source": "yahoo_finance",
            "status": "fresh",
            "as_of": upstream.get("as_of"),
            "ttl_seconds": ttl,
            "expires_at": expires_at,
            "payload": payload if include_payload else None,
            "payload_schema_version": 1,
            "upstream_etag": upstream.get("etag"),
            "upstream_fetched_at": nowdt.isoformat(),
            "created_at": nowdt.isoformat(),
            "updated_at": nowdt.isoformat()
        }
        snapshots.append(snap)
    else:
        snap_id = snap.get("id")
        # transition to fresh from any allowed state
        snap["status"] = "fresh"
        snap["as_of"] = upstream.get("as_of")
        snap["ttl_seconds"] = ttl
        snap["expires_at"] = expires_at
        snap["payload"] = payload if include_payload else snap.get("payload")
        snap["payload_schema_version"] = max(int(snap.get("payload_schema_version") or 1), 1)
        snap["upstream_etag"] = upstream.get("etag")
        snap["upstream_fetched_at"] = nowdt.isoformat()
        snap["updated_at"] = nowdt.isoformat()
        for i, s in enumerate(snapshots):
            if s.get("id") == snap_id:
                snapshots[i] = snap
                break
    _save("finance_snapshots.json", snapshots)

    # If historical_prices, upsert bars into ohlcv_bars
    if dataset == "historical_prices":
        bars_rows = _load("ohlcv_bars.json")
        by_key = {}
        for b in bars_rows:
            by_key[(b.get("security_id"), b.get("interval"), b.get("bar_time"))] = b
        interval_val = interval
        for b in payload.get("bars", []):
            bt = b.get("bar_time")
            key = (sec.get("id"), interval_val, bt)
            existing = by_key.get(key)
            row_now = _now()
            if existing is None:
                newb = {
                    "id": "bar_" + uuid.uuid4().hex,
                    "security_id": sec.get("id"),
                    "interval": interval_val,
                    "bar_time": bt,
                    "open": b.get("open"),
                    "high": b.get("high"),
                    "low": b.get("low"),
                    "close": b.get("close"),
                    "adj_close": b.get("adj_close"),
                    "volume": b.get("volume"),
                    "created_at": row_now,
                    "updated_at": row_now
                }
                bars_rows.append(newb)
                by_key[key] = newb
            else:
                existing["open"] = b.get("open")
                existing["high"] = b.get("high")
                existing["low"] = b.get("low")
                existing["close"] = b.get("close")
                existing["adj_close"] = b.get("adj_close")
                existing["volume"] = b.get("volume")
                existing["updated_at"] = row_now
        _save("ohlcv_bars.json", bars_rows)

    # log success (fetched_from_yahoo)
    cache_key = f"{dataset}:{sec.get('id')}:{params_fingerprint}"
    duration_ms = int((_nowdt() - t0).total_seconds() * 1000)
    ok, err, _, _ = _enforce_and_log(
        clients, client, tool_name, t_in, req_params, sec.get("id"),
        status="fetched_from_yahoo", http_status_code=200,
        response_snapshot_id=snap.get("id"), cache_key=cache_key, duration_ms=duration_ms
    )
    if not ok:
        return err

    # Response snapshot metadata (include payload if requested)
    out = dict(snap)
    if not include_payload:
        out["payload"] = None
    return {"snapshot": out}

def list_finance_requests(api_key, ticker=None, security_id=None, tool_name=None, status=None, from_created_at=None, to_created_at=None, page=None, page_size=None, **_extra):
    import json, os, datetime, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0290000" if __import__("os").path.isdir("./environment_mix/0290000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _nowdt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                s = s.replace(tzinfo=datetime.timezone.utc)
            return s.astimezone(datetime.timezone.utc).replace(microsecond=0)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        except Exception:
            return None

    def _day_floor(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _client_fingerprint(k):
        if not isinstance(k, str) or not k.strip():
            return None, None
        k = k.strip()
        return k, hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _resolve_client(k):
        clients = _load("api_clients.json")
        raw, dig = _client_fingerprint(k)
        for c in clients:
            if c.get("id") == raw or c.get("api_key_hash") == raw or c.get("api_key_hash") == dig:
                return c, clients
        return None, clients

    def _enforce_and_log_read(clients, client_row, tool_name_logged, parameters, http_status_code, error_code=None, error_message=None, duration_ms=None):
        # read calls still count towards limits and create exactly one finance_requests row.
        req_rows = _load("finance_requests.json")
        nowdt = _nowdt()
        now_iso = nowdt.isoformat()
        req_id = "req_" + uuid.uuid4().hex

        if not client_row:
            return False, _err("UNAUTHORIZED", "Invalid API key."), None, req_rows

        cur_day = _parse_dt(client_row.get("current_day"))
        if cur_day is None:
            cur_day = _day_floor(nowdt)
            client_row["current_day"] = cur_day.isoformat()
            client_row["requests_today"] = int(client_row.get("requests_today") or 0)
        if _day_floor(nowdt) != _day_floor(cur_day):
            client_row["current_day"] = _day_floor(nowdt).isoformat()
            client_row["requests_today"] = 0

        window_start = nowdt - datetime.timedelta(seconds=60)
        rpm_count = 0
        for r in req_rows:
            if r.get("api_client_id") != client_row.get("id"):
                continue
            rdt = _parse_dt(r.get("created_at"))
            if rdt and rdt >= window_start:
                rpm_count += 1

        limit_rpm = client_row.get("requests_per_minute_limit")
        limit_day = client_row.get("requests_per_day_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            limit_rpm = 60
        if not isinstance(limit_day, int) or limit_day < 1:
            limit_day = 10000

        reject = None
        if client_row.get("status") != "active":
            reject = ("UNAUTHORIZED", "API client is not active.")
        elif int(client_row.get("requests_today") or 0) >= int(limit_day):
            reject = ("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        elif rpm_count >= int(limit_rpm):
            reject = ("RATE_LIMIT", "Per-minute rate limit exceeded.")

        if reject:
            fr = {
                "id": req_id,
                "api_client_id": client_row.get("id"),
                "security_id": None,
                "tool_name": tool_name_logged,
                "ticker": "",  # list endpoint not tied to a ticker
                "parameters": parameters,
                "status": "failed",
                "http_status_code": 429,
                "error_code": reject[0],
                "error_message": reject[1],
                "cache_key": None,
                "response_snapshot_id": None,
                "duration_ms": duration_ms,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            req_rows.append(fr)
            client_row["updated_at"] = now_iso
            for i, c in enumerate(clients):
                if c.get("id") == client_row.get("id"):
                    clients[i] = client_row
                    break
            _save("api_clients.json", clients)
            _save("finance_requests.json", req_rows)
            return False, _err(reject[0], reject[1]), client_row, req_rows

        client_row["requests_today"] = int(client_row.get("requests_today") or 0) + 1
        client_row["updated_at"] = now_iso
        for i, c in enumerate(clients):
            if c.get("id") == client_row.get("id"):
                clients[i] = client_row
                break
        fr = {
            "id": req_id,
            "api_client_id": client_row.get("id"),
            "security_id": None,
            "tool_name": tool_name_logged,
            "ticker": "",
            "parameters": parameters,
            "status": "fetched_from_yahoo",
            "http_status_code": http_status_code,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": None,
            "response_snapshot_id": None,
            "duration_ms": duration_ms,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        req_rows.append(fr)
        _save("api_clients.json", clients)
        _save("finance_requests.json", req_rows)
        return True, None, client_row, req_rows

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.", field="api_key")
    if ticker is not None and (not isinstance(ticker, str) or not ticker.strip()):
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string when provided.", field="ticker")
    if ticker is not None and (len(ticker.strip()) < 1 or len(ticker.strip()) > 16):
        return _err("VALIDATION_ERROR", "ticker length must be between 1 and 16.", field="ticker")
    if security_id is not None and (not isinstance(security_id, str) or not security_id.strip()):
        return _err("VALIDATION_ERROR", "security_id must be a non-empty string when provided.", field="security_id")
    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "tool_name must be a string when provided.", field="tool_name")
        allowed_tools = ["get_historical_stock_prices","get_stock_info","get_yahoo_finance_news","get_stock_actions","get_financial_statement","get_holder_info","get_option_expiration_dates","get_option_chain","get_recommendations"]
        if tool_name not in allowed_tools:
            return _err("VALIDATION_ERROR", "tool_name must be a supported value.", field="tool_name", allowed=allowed_tools)
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
        allowed_status = ["received","served_from_cache","fetched_from_yahoo","failed"]
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be a supported value.", field="status", allowed=allowed_status)
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    from_dt = None
    to_dt = None
    if from_created_at is not None:
        if not isinstance(from_created_at, str):
            return _err("VALIDATION_ERROR", "from_created_at must be a string (RFC3339) when provided.", field="from_created_at")
        from_dt = _parse_dt(from_created_at)
        if from_dt is None:
            return _err("VALIDATION_ERROR", "from_created_at must be RFC3339 parseable.", field="from_created_at")
    if to_created_at is not None:
        if not isinstance(to_created_at, str):
            return _err("VALIDATION_ERROR", "to_created_at must be a string (RFC3339) when provided.", field="to_created_at")
        to_dt = _parse_dt(to_created_at)
        if to_dt is None:
            return _err("VALIDATION_ERROR", "to_created_at must be RFC3339 parseable.", field="to_created_at")
    if from_dt and to_dt and from_dt > to_dt:
        return _err("VALIDATION_ERROR", "from_created_at must be <= to_created_at.", field="from_created_at")

    # Auth
    client, clients = _resolve_client(api_key)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key.")

    t0 = _nowdt()
    # Enforce quotas and log this read as a finance_requests row using a valid tool_name enum.
    # We log under get_stock_info with action=list_finance_requests because schema doesn't include list tool.
    log_params = {
        "action": "list_finance_requests",
        "ticker": ticker,
        "security_id": security_id,
        "tool_name": tool_name,
        "status": status,
        "from_created_at": from_created_at,
        "to_created_at": to_created_at,
        "page": page,
        "page_size": page_size
    }
    duration_ms = int((_nowdt() - t0).total_seconds() * 1000)
    ok, err, _, _ = _enforce_and_log_read(clients, client, "get_stock_info", log_params, 200, duration_ms=duration_ms)
    if not ok:
        return err

    rows = _load("finance_requests.json")
    # filter to calling client
    filtered = [r for r in rows if r.get("api_client_id") == client.get("id")]

    if ticker is not None:
        t = ticker.strip()
        filtered = [r for r in filtered if r.get("ticker") == t]
    if security_id is not None:
        sid = security_id.strip()
        filtered = [r for r in filtered if r.get("security_id") == sid]
    if tool_name is not None:
        filtered = [r for r in filtered if r.get("tool_name") == tool_name]
    if status is not None:
        filtered = [r for r in filtered if r.get("status") == status]
    if from_dt is not None:
        filtered = [r for r in filtered if (_parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) >= from_dt)]
    if to_dt is not None:
        filtered = [r for r in filtered if (_parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) <= to_dt)]

    # sort by created_at desc
    filtered.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = filtered[start:end]
    has_more = end < total

    return {
        "items": page_items,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more
    }
